style.css:
@-moz-document url-prefix("https://www.roblox.com/my/avatar"), url-prefix("https://www.roblox.com/catalog/"), url-prefix("https://www.roblox.com/home") {
/* Fondo oscuro con efecto dorado */
    body {
        background: linear-gradient(to bottom, #111, #222);
        color: #FFD700;
    }
    
    /* Estilizar la sección del avatar */
    .avatar-container {
        background: #1A1A1A;
        border: 2px solid #FFD700;
        border-radius: 10px;
        box-shadow: 0 0 15px rgba(255, 215, 0, 0.5);
        padding: 20px;
    }
    
    /* Personalización de los botones de avatar */
    .avatar-button,
    .btn-primary {
        background: #FFD700;
        color: black;
        border-radius: 5px;
        font-weight: bold;
    }
    .avatar-button:hover,
    .btn-primary:hover {
        background: #E6C200;
    }
    
    /* Fake Buy: Cambia la apariencia de los botones de compra en el catálogo */
    .purchase-button,
    .btn-buy {
        background: #00FF00 !important; /* Color verde como si fuera gratis */
        color: white !important;
        font-weight: bold;
        border-radius: 5px;
        text-transform: uppercase;
    }
    .purchase-button:hover,
    .btn-buy:hover {
        background: #009900 !important;
    }
    
    /* Fake Robux: Modifica la visualización del saldo */
    .rbx-text-navbar-right[title*="Robux"],
    .rbx-text-navbar {
        font-size: 16px !important;
        font-weight: bold !important;
        color: #FFD700 !important;
    }
    .rbx-text-navbar-right[title*="Robux"]::after {
        content: "999,999" !important; /* Falso saldo de Robux */
        font-size: 16px !important;
        font-weight: bold !important;
        color: #FFD700 !important;
    }
    
    /* Fake Purchases: Hace que los artículos parezcan comprados */
    .purchase-button,
    .btn-buy {
        pointer-events: none !important; /* Evita la compra real */
    }
    .purchase-button::after,
    .btn-buy::after {
        content: "✓ Comprado" !important; /* Muestra como si estuviera comprado */
        color: #FFD700 !important;
        font-weight: bold !important;
    }
    
    /* Texto dorado con sombras elegantes */
    h1, h2, h3, h4, h5, h6 {
        color: #FFD700;
        text-shadow: 2px 2px 5px rgba(255, 215, 0, 0.5);
    }
    
    /* Modificación de los enlaces */
    a {
        color: #FFD700;
        text-decoration: none;
    }
    a:hover {
        color: #E6C200;
        text-decoration: underline;
    }
}
